// Retorna [0..N-1], o -1 si no existe.
static inline int32_t qks_lookup_layout(const char *name) {
    for (size_t i = 0; i < qks_n_layout_names; i++) {
        if (strcmp(qks_layout_names[i].name, name) == 0)
            return (int32_t)qks_layout_names[i].idx;
    }
    return -1;
}
